import itertools
from scipy.optimize import minimize_scalar
y=dA_dt; V=np.var(y)
Ft={'1':np.ones_like(t),'t':t,'t2':t**2,'1/t':1/t,'exp-t':np.exp(-t),'sqrt t':np.sqrt(t),'log t':np.log(t),'t3':t**3,'1/(1+t)':1/(1+t),'exp-t/2':np.exp(-t/2),'t^1.5':t**1.5}
Ga={'1':np.ones_like(A),'A':A,'A2':A**2,'A3':A**3,'A4':A**4,'1/A':1/A,'sqrtA':np.sqrt(A),'expmA':np.exp(-A),'lnA':np.log(A),'A^1.5':A**1.5,'expA':np.exp(A)}
prods={(fn,gn):f*g for fn,f in Ft.items() for gn,g in Ga.items()}
keys=list(prods.keys())
def score(c,k1,k2):
    base=t/(1+c*t)*A**2
    X=np.column_stack([base,t**2,prods[k1],prods[k2]])
    b=np.linalg.lstsq(X,y,rcond=None)[0]
    return np.mean((y-X@b)**2)/V
# coarse
coarse=[]
for c in np.linspace(0.02,2,50):
    for k1,k2 in itertools.combinations(keys,2):
        coarse.append((score(c,k1,k2),c,k1,k2))
coarse.sort(key=lambda x:x[0])
seen=set(); top=[]
for s,c,k1,k2 in coarse[:300]:
    if (k1,k2) in seen: continue
    seen.add((k1,k2)); top.append((k1,k2,c))
    if len(top)>=15: break
out=[]
for k1,k2,c0 in top:
    r=minimize_scalar(lambda c: score(c,k1,k2),bounds=(0.001,5),method='bounded')
    out.append((r.fun,round(r.x,5),k1,k2))
out.sort(key=lambda x:x[0])
for o in out[:8]: print(o)
